        [[-1.7, -73.6], [-32.0, -65.6], [-24.3, -65.6], [-16.8, -65.3], [-9.4, -64.7], [-1.4, -64.2], [7.5, -65.7], [15.2, -65.3], [22.8, -64.1], [30.7, -64.6], [-41.1, -57.0], [-33.0, -57.2], [-25.2, -56.4], [-17.4, -56.5], [-8.8, -57.2], [-1.8, -56.5], [6.8, -57.1], [15.4, -56.9], [22.2, -57.6], [31.2, -57.3], [39.6, -57.5], [-48.4, -48.4], [-40.6, -48.5], [-32.7, -48.2], [-24.9, -49.3], [-17.4, -48.6], [-9.6, -49.0], [-0.4, -48.1], [7.0, -48.2], [14.8, -49.5], [23.7, -49.4], [31.0, -49.4], [39.7, -48.4], [47.1, -49.0], [-48.9, -41.2], [-41.1, -41.7], [-32.3, -41.4], [-24.5, -40.1], [22.5, -41.8], [30.4, -41.3], [38.9, -41.0], [47.0, -41.7], [-49.2, -32.8], [-40.7, -32.3], [-32.7, -33.4], [31.2, -33.1], [38.8, -33.3], [48.1, -32.1], [-48.5, -24.4], [-40.5, -25.0], [-32.1, -24.9], [-24.7, -24.8], [-48.8, -16.1], [-41.1, -16.0], [-32.9, -16.7], [-24.1, -16.2], [-17.1, -16.4], [-48.3, -8.7], [-40.3, -9.5], [-33.5, -9.4], [-24.4, -9.7], [-16.2, -8.4], [-9.4, -9.3], [-0.3, -8.7], [8.1, -8.4], [15.1, -9.4], [22.7, -9.2], [-41.7, -0.6], [-33.3, -0.9], [-24.6, -0.8], [-16.7, -0.8], [-9.4, -1.0], [-0.6, -1.4], [7.6, -0.6], [15.5, -1.6], [22.5, -1.0], [31.7, -0.8], [39.5, -1.1], [-24.0, 6.6], [-17.3, 7.9], [-9.2, 7.1], [-1.1, 7.4], [6.8, 7.0], [15.4, 6.9], [24.1, 7.5], [30.4, 6.5], [40.1, 6.2], [47.7, 7.6], [14.4, 15.5], [22.8, 15.8], [31.4, 15.8], [39.7, 14.7], [47.8, 15.3], [31.3, 23.1], [38.4, 23.4], [48.1, 23.5], [56.1, 22.6], [-56.6, 30.1], [-48.5, 30.8], [-40.3, 30.4], [-32.4, 30.6], [31.3, 31.2], [39.3, 30.2], [46.5, 30.8], [54.8, 31.8], [-56.3, 39.9], [-48.4, 38.5], [-41.3, 39.1], [-31.9, 38.2], [30.7, 39.3], [39.3, 39.8], [47.7, 38.8], [-48.3, 46.6], [-40.4, 47.5], [-33.7, 47.5], [-24.4, 46.4], [-17.1, 46.8], [14.7, 47.7], [23.7, 46.6], [31.7, 46.3], [38.2, 47.4], [46.6, 47.7], [-49.4, 55.5], [-41.0, 54.5], [-33.3, 54.1], [-24.4, 55.6], [-16.3, 55.5], [-8.2, 55.4], [-1.8, 56.0], [8.1, 54.8], [15.2, 55.6], [23.8, 55.4], [30.3, 55.0], [39.0, 54.4], [46.7, 54.9], [-33.3, 63.1], [-24.9, 63.5], [-17.3, 63.0], [-8.6, 63.1], [-1.1, 62.2], [7.5, 63.1], [15.6, 62.4], [23.1, 63.1], [30.7, 62.2], [-16.9, 71.2], [-8.7, 71.5], [-1.1, 70.2], [6.9, 71.5], [14.5, 71.2]]
    ]
    /// [letter, cy, rx, ry]: an O is cut as its whole disc.
    static let open: [[Double]] = [[1, -1.6, 67.8, 76.0], [4, -0.3, 67.5, 75.1]]
    static let ls = 1.22 / 156.28, kr = 0.066, cn = 48, period = 9.0, count = 2200

    struct Dot { let x, y, z, hr, r, ja: Double; let jw, jp: [Double] }
    struct Current { let k, push: [Double]; let amp, w, ph: Double }

    /// The same Lehmer generator, seed 7, as the desktop, so the dots match.
    private struct Rng { var seed: Int64 = 7; mutating func next() -> Double { seed = (seed * 16807) % 2147483647; return Double(seed) / 2147483647 } }

    static let built: (dots: [Dot], currents: [Current]) = {
        var g = Rng()
        var dots: [Dot] = []
        while dots.count < count {
            let x = g.next() * 2 - 1, y = g.next() * 2 - 1, z = g.next() * 2 - 1, rr = x * x + y * y + z * z
            if rr > 1 || rr < 0.04 || g.next() > 0.4 + 0.6 * rr * rr { continue }
            let r = g.next() < 0.08 ? 1.8 + g.next() : 0.8 + g.next() * 0.6
            let ja = 0.02 + g.next() * 0.03
            let jw = [1 + floor(g.next() * 3), 1 + floor(g.next() * 3), 1 + floor(g.next() * 3)]
            let jp = [g.next() * 6.283, g.next() * 6.283, g.next() * 6.283]
            dots.append(Dot(x: x, y: y, z: z, hr: rr.squareRoot(), r: r, ja: ja, jw: jw, jp: jp))
        }
        func unit() -> [Double] { let a = g.next() * 6.283, z = g.next() * 2 - 1, s = (1 - z * z).squareRoot(); return [s * cos(a), s * sin(a), z] }
        var cur: [Current] = []
        for _ in 0..<5 {
            let k = unit().map { $0 * (1.2 + g.next() * 1.8) }
            let push = unit()
            cur.append(Current(k: k, push: push, amp: (0.5 + g.next() * 0.5) / 5.0.squareRoot(), w: 1 + floor(g.next() * 2), ph: g.next() * 6.283))
        }
        return (dots, cur)
    }()

    /// Each letter's distance to its cut, worked out once at a coarse resolution (negative inside the letter).
    static let cuts: [[Float]] = word.enumerated().map { (i, pts) in
        let lp = pts.map { [(i % 2 == 1 ? -$0[0] : $0[0]) * ls, $0[1] * ls] }
        var g = [Float](repeating: 0, count: cn * cn)
        for r in 0..<cn { for c in 0..<cn {
            let x = -1 + 2 * (Double(c) + 0.5) / Double(cn), y = -1 + 2 * (Double(r) + 0.5) / Double(cn)
            var m = 9.0
            for p in lp { let dx = x - p[0], dy = y - p[1]; m = min(m, dx * dx + dy * dy) }
            var gap = m.squareRoot() - kr
            for o in open where Int(o[0]) == i { let u = x / ls, v = y / ls - o[1]; if u * u / (o[2] * o[2]) + v * v / (o[3] * o[3]) < 1 { gap = -1 } }
            g[r * cn + c] = Float(gap)
        } }
        return g
    }

    static func gap(_ i: Int, _ x: Double, _ y: Double) -> Double {
        let c = max(0, min(cn - 1, Int(floor((x + 1) / 2 * Double(cn))))), r = max(0, min(cn - 1, Int(floor((y + 1) / 2 * Double(cn)))))
        return Double(cuts[i][r * cn + c])
    }

    /// Which letter is cut at time t (seconds), 0...5 for K O S M O S: it changes while the orb is edge-on.
    static func letter(at t: Double) -> Int {
        let a = 2 * Double.pi * t / period, step = Int(floor((a + Double.pi / 2) / Double.pi))
        return ((step % 6) + 6) % 6
    }

    /// Every dot at time t, as the desktop's place().
    static func place(_ t: Double) -> [Placed] {
        let a = 2 * Double.pi * t / period, ca = cos(a), sa = sin(a), ph = a
        let pha = a + Double.pi / 2, step = floor(pha / Double.pi), into = pha - step * Double.pi
        let cur = ((Int(step) % 6) + 6) % 6, prev = (cur + 5) % 6, wNew = min(1, into / 0.5)
        var out: [Placed] = []
        out.reserveCapacity(count)
        for d in built.dots {
            var ox = d.x, oy = d.y, oz = d.z
            for c in built.currents {
                let s = 0.42 * c.amp * sin(c.k[0] * d.x + c.k[1] * d.y + c.k[2] * d.z + c.w * ph + c.ph)
                ox += c.push[0] * s; oy += c.push[1] * s; oz += c.push[2] * s
            }
            ox += d.ja * sin(d.jw[0] * ph + d.jp[0]); oy += d.ja * sin(d.jw[1] * ph + d.jp[1]); oz += d.ja * sin(d.jw[2] * ph + d.jp[2])
            let m = (ox * ox + oy * oy + oz * oz).squareRoot()
            var mm = m / pow(1 + pow(m, 8), 1.0 / 8)
            let skin = max(0, min(1, (d.hr - 0.72) / 0.18))
            mm += (min(d.hr, 0.995) - mm) * skin
            if m > 0 { ox *= mm / m; oy *= mm / m; oz *= mm / m }
            let vc = max(0, min(1, gap(cur, ox, oy) / 0.035)), vp = max(0, min(1, gap(prev, ox, oy) / 0.035))
            let vis = 1 - max(wNew * (1 - vc), (1 - wNew) * (1 - vp))
            if vis > 0 { out.append(Placed(x: ox * ca + oz * sa, y: oy, z: -ox * sa + oz * ca, r: d.r, vis: vis)) }
        }
        return out
    }

    /// The whole loop: six letters, one per half turn.
    static let loop = period * 3
    /// The still frame (the K facing) for Reduce Motion, worked out once.
    static let stillDots: [Placed] = place(0)

    /// Every orb on screen in one frame shares one placing (review round 2: each did its own). The time is rounded to a
    /// 30th of a second, the orb's frame rate, so orbs drawn in the same frame ask for the same t. Main actor, as SwiftUI
    /// draws (review round 3: unisolated, it would race under a later off-thread caller).
    @MainActor private static var lastT = Double.nan
    @MainActor private static var lastPts: [Placed] = []
    @MainActor static func placeShared(_ t: Double) -> [Placed] {
        let q = (t * 30).rounded() / 30
        if q != lastT { lastT = q; lastPts = place(q) }
        return lastPts
    }
    /// Builds the dots and the letter cuts away from the main thread, so the first orb shown does not stall a frame.
    static func warm() { DispatchQueue.global(qos: .userInitiated).async { _ = built.dots.count; _ = cuts.count; _ = stillDots.count } }

    /// One circle to fill, in points within a square of side `side`.
    struct Circle { let cx: Double; let cy: Double; let radius: Double }
    static let steps = 8
    /// The dots grouped into `steps` strengths (group k is drawn at opacity (k + 0.5) / steps), as the desktop paints:
    /// one path per group, not a fill per dot. Dots fainter than the faintest step are left out.
    static func groups(_ pts: [Placed], side: Double, scale: Double) -> [[Circle]] {
        var gs = Array(repeating: [Circle](), count: steps)
        let rad = side * 0.46, cam = 6.0, px = side * scale * 0.009
        for p in pts {
            let f = cam / (cam + p.z), front = max(0, min(1, (1 - p.z) / 2))
            let alpha = (0.25 + 0.75 * pow(front, 1.4)) * p.vis
            if alpha < 1 / Double(steps) { continue }
            gs[min(steps - 1, Int(floor(alpha * Double(steps))))].append(Circle(cx: side / 2 + p.x * rad * f, cy: side / 2 + p.y * rad * f, radius: max(0.35 / scale, p.r * px * f / scale)))
        }
        return gs
    }
}
